function cn(...classes: Array<string | false | null | undefined>) { return classes.filter(Boolean).join(" "); }

function Pill({ children, tone = "slate" }: { children: React.ReactNode; tone?: "slate" | "cyan" | "red" | "amber" | "violet" | "green" }) {
  const tones = { slate: "bg-slate-500/10 text-slate-300 border-slate-500/20", cyan: "bg-cyan-400/10 text-cyan-300 border-cyan-400/20", red: "bg-rose-400/10 text-rose-300 border-rose-400/20", amber: "bg-amber-400/10 text-amber-300 border-amber-400/20", violet: "bg-violet-400/10 text-violet-300 border-violet-400/20", green: "bg-emerald-400/10 text-emerald-300 border-emerald-400/20" };
  return <span className={cn("inline-flex items-center gap-1 rounded-md border px-2 py-1 text-[12px] font-bold tracking-wider", tones[tone])}>{children}</span>;
}

function SectionHeader({ eyebrow, title, subtitle, action }: { eyebrow: string; title: string; subtitle?: string; action?: React.ReactNode }) {
  return <div className="mb-6 flex items-end justify-between gap-4"><div><p className="font-mono text-[12px] font-medium uppercase tracking-[.22em] text-cyan-300/70">{eyebrow}</p><h1 className="mt-2 text-2xl font-extrabold tracking-tight text-white sm:text-3xl">{title}</h1>{subtitle && <p className="mt-2 text-sm text-slate-400">{subtitle}</p>}</div>{action}</div>;
}

function MiniSpark({ color = "#53d3f1", negative = false }: { color?: string; negative?: boolean }) {
  const data = negative ? [9, 13, 11, 17, 15, 21, 20, 26].map((v, i) => ({ v: v + (i % 2 ? 1 : -1) })) : [14, 12, 18, 16, 22, 20, 29, 26].map(v => ({ v }));
  return <div className="h-8 w-20"><ResponsiveContainer width="100%" height="100%"><AreaChart data={data}><Area type="monotone" dataKey="v" stroke={color} fill={color} fillOpacity={.12} strokeWidth={1.8} dot={false} /></AreaChart></ResponsiveContainer></div>;
}

function KpiCard({ label, value, detail, trend, icon: Icon, color = "cyan", negative = false }: { label: string; value: string; detail: string; trend: string; icon: React.ElementType; color?: string; negative?: boolean }) {
  const iconColor: Record<string, string> = { cyan: "text-cyan-300 bg-cyan-400/10", red: "text-rose-300 bg-rose-400/10", amber: "text-amber-300 bg-amber-400/10", violet: "text-violet-300 bg-violet-400/10" };
  return <div className="card-border rounded-xl bg-[#101725]/90 p-4 transition duration-200 hover:-translate-y-0.5 hover:border-slate-600/70"><div className="flex items-start justify-between"><div className={cn("rounded-lg p-2.5", iconColor[color])}><Icon size={17} /></div><MiniSpark color={color === "red" ? "#ef6d7a" : color === "amber" ? "#fca86a" : color === "violet" ? "#aa91f8" : "#53d3f1"} negative={negative} /></div><p className="mt-4 text-sm font-medium text-slate-400">{label}</p><div className="mt-1 flex items-end justify-between gap-2"><p className="text-2xl font-bold tracking-tight text-white">{value}</p><span className={cn("mb-1 flex items-center text-[12px] font-bold", negative ? "text-rose-300" : "text-emerald-300")}>{negative ? <ArrowDownRight size={12} /> : <ArrowUpRight size={12} />}{trend}</span></div><p className="mt-1 text-[12px] text-slate-500">{detail}</p></div>;
}

