      <div className="card-border scanline rounded-xl bg-[#101725]/90 p-5"><div className="mb-5 flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-2"><Activity size={16} className="text-cyan-300" /><h2 className="text-sm font-bold text-white">Network activity</h2><Pill tone="cyan"><span className="status-dot bg-cyan-300" />LIVE</Pill></div><p className="mt-1 text-sm text-slate-500">Packet volume and malicious flow detections</p></div><div className="flex items-center gap-1 rounded-lg border border-slate-700/60 bg-slate-950/30 p-1">{["1H", "24H", "7D"].map(item => <button key={item} onClick={() => setRange(item)} className={cn("rounded px-2.5 py-1 text-[12px] font-bold", range === item ? "bg-cyan-400/15 text-cyan-200" : "text-slate-500 hover:text-slate-300")}>{item}</button>)}</div></div><div className="h-[230px] w-full"><ResponsiveContainer width="100%" height="100%"><AreaChart data={trafficData} margin={{ top: 4, right: 2, left: -20, bottom: 0 }}><defs><linearGradient id="packets" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#53d3f1" stopOpacity={.24} /><stop offset="95%" stopColor="#53d3f1" stopOpacity={0} /></linearGradient><linearGradient id="threats" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#ef6d7a" stopOpacity={.22} /><stop offset="95%" stopColor="#ef6d7a" stopOpacity={0} /></linearGradient></defs><CartesianGrid strokeDasharray="3 5" /><XAxis dataKey="time" tick={{ fill: "#65748a", fontSize: 10 }} axisLine={false} tickLine={false} interval={2} /><YAxis tick={{ fill: "#65748a", fontSize: 10 }} axisLine={false} tickLine={false} /><Tooltip contentStyle={{ background: "#101a2a", border: "1px solid #2d415c", borderRadius: 8, fontSize: 11 }} /><Area type="monotone" dataKey="packets" name="Packets (k)" stroke="#53d3f1" fill="url(#packets)" strokeWidth={2} /><Area type="monotone" dataKey="threats" name="Threats" stroke="#ef6d7a" fill="url(#threats)" strokeWidth={2} /></AreaChart></ResponsiveContainer></div><div className="mt-4 flex items-center gap-5 text-[12px] text-slate-500"><span className="flex items-center gap-2"><i className="h-1.5 w-5 rounded-full bg-cyan-300" />PACKETS ANALYZED</span><span className="flex items-center gap-2"><i className="h-1.5 w-5 rounded-full bg-rose-300" />THREATS FLAGGED</span><span className="ml-auto font-mono text-slate-600">UTC · AUTO REFRESH 30S</span></div></div>
