function MonitorView() {
  const [ingesting, setIngesting] = useState(false);
  const simulation = trpc.advsecure.simulateTraffic.useMutation();
  const run = () => { setIngesting(true); toast.info("Simulation queued", { description: "Generating a CICIDS2017 traffic batch for inference." }); simulation.mutate({ source: "cicids2017", model: "base_xgboost.pkl" }, { onSuccess: result => { setIngesting(false); toast.success("Traffic batch analyzed", { description: `${result.rows.toLocaleString()} flows classified · ${result.threats} threats persisted.` }); }, onError: error => { setIngesting(false); toast.error("Simulation failed", { description: error.message }); } }); };
  return <><SectionHeader eyebrow="OPERATIONS / TELEMETRY" title="Traffic monitor" subtitle="Ingest, validate, and route network traffic into the detection pipeline." action={<button onClick={run} className="flex items-center gap-2 rounded-lg bg-cyan-300 px-3 py-2 text-sm font-extrabold text-slate-950 transition hover:bg-cyan-200 active:scale-[.98]"><Play size={13} fill="currentColor" />{ingesting ? "RUNNING..." : "SIMULATE TRAFFIC"}</button>} /><div className="grid gap-4 lg:grid-cols-[1.1fr_.9fr]"><div className="card-border rounded-xl bg-[#101725]/90 p-5"><div className="flex items-center justify-between"><div><h2 className="text-sm font-bold text-white">Traffic ingestion</h2><p className="mt-1 text-sm text-slate-500">Drop a CSV or replay a known dataset</p></div><Pill tone="green"><span className="status-dot bg-emerald-300" />READY</Pill></div><div className="mt-5 rounded-xl border border-dashed border-slate-600/60 bg-slate-950/20 p-8 text-center transition hover:border-cyan-300/50"><div className="mx-auto flex h-12 w-12 items-center justify-center rounded-xl bg-cyan-400/10 text-cyan-300"><UploadCloud size={22} /></div><p className="mt-4 text-sm font-semibold text-slate-200">Upload network telemetry</p><p className="mx-auto mt-1 max-w-sm text-sm leading-5 text-slate-500">CSV files from CICIDS2017 or your sensor export. Validation and preprocessing are applied automatically.</p><button onClick={() => toast.success("File picker ready", { description: "Connect a dataset to begin ingestion." })} className="mt-5 rounded-lg border border-slate-700/70 px-4 py-2 text-sm font-bold text-slate-300 hover:border-cyan-300/40 hover:text-cyan-200">BROWSE FILES</button></div><div className="mt-5 grid grid-cols-3 gap-3">{[{ label: "Validation", value: "READY", icon: FileCode2 }, { label: "Preprocessing", value: "SCALER V1.3", icon: SlidersHorizontal }, { label: "Queue", value: "0 JOBS", icon: Layers3 }].map(item => <div key={item.label} className="rounded-lg border border-slate-800/70 bg-slate-950/20 p-3"><item.icon size={14} className="text-slate-500" /><p className="mt-3 text-[12px] text-slate-500">{item.label}</p><p className="mt-1 font-mono text-[12px] font-bold text-cyan-300">{item.value}</p></div>)}</div></div><div className="card-border rounded-xl bg-[#101725]/90 p-5"><div className="flex items-center gap-2"><Cloud size={16} className="text-violet-300" /><h2 className="text-sm font-bold text-white">Pipeline status</h2></div><p className="mt-1 text-sm text-slate-500">Current processing stages</p><div className="mt-6 space-y-5">{[{ label: "Sensor connection", detail: "edge-proxy-01 · 10.44.0.0/16", progress: 100, status: "Connected" }, { label: "Data validation", detail: "Schema + missing values", progress: 100, status: "Passing" }, { label: "Feature scaling", detail: "scaler.pkl · 78 features", progress: 100, status: "Ready" }, { label: "Inference queue", detail: "XGBoost / DNN routing", progress: 72, status: "Active" }].map((item, i) => <div key={item.label}><div className="mb-2 flex items-center justify-between"><div className="flex items-center gap-2"><span className={cn("flex h-5 w-5 items-center justify-center rounded-full text-[12px] font-bold", item.progress === 100 ? "bg-emerald-400/15 text-emerald-300" : "bg-cyan-400/15 text-cyan-300")}>{i + 1}</span><div><p className="text-sm font-semibold text-slate-300">{item.label}</p><p className="text-[12px] text-slate-600">{item.detail}</p></div></div><span className="font-mono text-[12px] text-slate-500">{item.status}</span></div><div className="ml-7 h-1 rounded-full bg-slate-800"><div className={cn("h-full rounded-full", item.progress === 100 ? "bg-emerald-400" : "bg-cyan-300")} style={{ width: `${item.progress}%` }} /></div></div>)}</div></div></div></>;
}

function ModelsView() {
  const [selected, setSelected] = useState("xgb");
  return <><SectionHeader eyebrow="INTELLIGENCE / REGISTRY" title="IDS models" subtitle="Select an inference engine and inspect its current operating envelope." action={<button onClick={() => toast.success("Registry synchronized", { description: "2 model artifacts verified against the pipeline." })} className="flex items-center gap-2 rounded-lg border border-slate-700/60 bg-slate-900/30 px-3 py-2 text-sm font-bold text-slate-300 hover:border-cyan-300/40 hover:text-cyan-200"><RefreshCw size={13} />SYNC REGISTRY</button>} /><div className="grid gap-4 lg:grid-cols-2">{[{ id: "xgb", name: "XGBoost IDS", file: "base_xgboost.pkl", desc: "Fast tree-based inference for high-volume packet triage.", accuracy: "96.4%", latency: "8ms", version: "v1.4.2", icon: Zap, color: "cyan", tags: ["FAST INFERENCE", "PRODUCTION"] }, { id: "dnn", name: "Deep Neural Network", file: "base_dnn.keras", desc: "Gradient-capable model for deep behavioral analysis and lab testing.", accuracy: "94.8%", latency: "42ms", version: "v1.2.0", icon: BrainCircuit, color: "violet", tags: ["GRADIENT ACCESS", "RESEARCH"] }].map(model => <button key={model.id} onClick={() => setSelected(model.id)} className={cn("card-border text-left rounded-xl bg-[#101725]/90 p-5 transition hover:-translate-y-0.5", selected === model.id ? "border-cyan-300/60 ring-1 ring-cyan-300/20" : "hover:border-slate-600/70")}><div className="flex items-start justify-between"><div className={cn("rounded-xl p-3", model.color === "cyan" ? "bg-cyan-400/10 text-cyan-300" : "bg-violet-400/10 text-violet-300")}><model.icon size={20} /></div><div className="flex gap-2">{model.tags.map(tag => <Pill key={tag} tone={tag === "PRODUCTION" ? "green" : model.color === "cyan" ? "cyan" : "violet"}>{tag}</Pill>)}</div></div><h2 className="mt-5 text-base font-bold text-white">{model.name}</h2><p className="mt-1 font-mono text-[12px] text-slate-500">{model.file} · {model.version}</p><p className="mt-4 max-w-md text-sm leading-5 text-slate-400">{model.desc}</p><div className="mt-5 grid grid-cols-2 gap-3 border-t border-slate-800/70 pt-4"><div><p className="text-[12px] text-slate-600">VALIDATION ACCURACY</p><p className="mt-1 text-lg font-bold text-white">{model.accuracy}</p></div><div><p className="text-[12px] text-slate-600">P95 LATENCY</p><p className="mt-1 text-lg font-bold text-white">{model.latency}</p></div></div><div className="mt-4 flex items-center gap-2 text-[12px] font-bold tracking-wider text-slate-500">{selected === model.id ? <><span className="status-dot bg-emerald-300" />ACTIVE INFERENCE ENGINE</> : "CLICK TO SELECT"}</div></button>)}</div><div className="card-border mt-4 rounded-xl bg-[#101725]/90 p-5"><div className="flex items-center justify-between"><div><h2 className="text-sm font-bold text-white">Model evaluation history</h2><p className="mt-1 text-sm text-slate-500">Validation accuracy across recent releases</p></div><Pill tone="slate">LAST 30 DAYS</Pill></div><div className="mt-5 h-[190px]"><ResponsiveContainer width="100%" height="100%"><LineChart data={[{ day: "Aug 12", xgb: 94.8, dnn: 92.9 }, { day: "Aug 16", xgb: 95.2, dnn: 93.1 }, { day: "Aug 20", xgb: 95.6, dnn: 93.5 }, { day: "Aug 24", xgb: 95.9, dnn: 94.1 }, { day: "Aug 28", xgb: 96.1, dnn: 94.2 }, { day: "Sep 01", xgb: 96.4, dnn: 94.8 }]}><CartesianGrid strokeDasharray="3 5" /><XAxis dataKey="day" tick={{ fill: "#65748a", fontSize: 10 }} axisLine={false} tickLine={false} /><YAxis domain={[90, 98]} tick={{ fill: "#65748a", fontSize: 10 }} axisLine={false} tickLine={false} /><Tooltip contentStyle={{ background: "#101a2a", border: "1px solid #2d415c", borderRadius: 8, fontSize: 11 }} /><Line type="monotone" dataKey="xgb" name="XGBoost" stroke="#53d3f1" strokeWidth={2} dot={{ r: 3, fill: "#53d3f1" }} /><Line type="monotone" dataKey="dnn" name="DNN" stroke="#aa91f8" strokeWidth={2} dot={{ r: 3, fill: "#aa91f8" }} /></LineChart></ResponsiveContainer></div></div></>;
}

function AdversarialView() {
  const [epsilon, setEpsilon] = useState(0.03); const [running, setRunning] = useState(false); const [completed, setCompleted] = useState(false);
  const adversarial = trpc.advsecure.runAdversarial.useMutation();
  const run = () => { setRunning(true); setCompleted(false); adversarial.mutate({ epsilon, model: "base_dnn.keras" }, { onSuccess: result => { setRunning(false); setCompleted(true); toast.success("FGSM run completed", { description: `Epsilon ${result.epsilon.toFixed(2)} · DNN accuracy ${result.adversarialAccuracy}% after perturbation.` }); }, onError: error => { setRunning(false); toast.error("FGSM run failed", { description: error.message }); } }); };
  return <><SectionHeader eyebrow="INTELLIGENCE / ROBUSTNESS" title="Adversarial lab" subtitle="Measure how easily the detection boundary can be manipulated with FGSM perturbations." action={<Pill tone="amber"><Bug size={12} />SAFE SIMULATION MODE</Pill>} /><div className="grid gap-4 xl:grid-cols-[1.1fr_.9fr]"><div className="card-border rounded-xl bg-[#101725]/90 p-5"><div className="flex items-start justify-between"><div><h2 className="text-sm font-bold text-white">FGSM experiment</h2><p className="mt-1 text-sm text-slate-500">Fast Gradient Sign Method · controlled evaluation</p></div><div className="rounded-lg bg-amber-400/10 p-2 text-amber-300"><Target size={17} /></div></div><div className="mt-6 space-y-5"><label className="block"><div className="mb-2 flex justify-between"><span className="text-sm font-semibold text-slate-300">Target model</span><span className="font-mono text-[12px] text-violet-300">base_dnn.keras</span></div><div className="flex items-center gap-3 rounded-lg border border-slate-700/70 bg-slate-950/30 p-3"><BrainCircuit size={15} className="text-violet-300" /><span className="text-sm text-slate-300">Deep Neural Network</span><ChevronDown size={14} className="ml-auto text-slate-600" /></div></label><label className="block"><div className="mb-3 flex justify-between"><span className="text-sm font-semibold text-slate-300">Perturbation strength <span className="font-normal text-slate-500">(epsilon)</span></span><span className="rounded bg-amber-400/10 px-2 py-1 font-mono text-sm font-bold text-amber-300">{epsilon.toFixed(2)}</span></div><input type="range" min="0.01" max="0.10" step="0.01" value={epsilon} onChange={e => setEpsilon(Number(e.target.value))} className="w-full accent-amber-300" /><div className="mt-2 flex justify-between font-mono text-[12px] text-slate-600"><span>0.01 / LOW</span><span>0.10 / HIGH</span></div></label><div className="rounded-lg border border-slate-800/70 bg-slate-950/30 p-4"><div className="flex items-start gap-3"><CircleHelp size={15} className="mt-0.5 shrink-0 text-slate-500" /><p className="text-[12px] leading-5 text-slate-400">AdvSecure applies bounded perturbations to a held-out validation batch. No external traffic is generated and no production policy is changed.</p></div></div><button onClick={run} disabled={running} className="flex w-full items-center justify-center gap-2 rounded-lg bg-amber-300 py-3 text-sm font-extrabold text-slate-950 transition hover:bg-amber-200 disabled:cursor-wait disabled:opacity-70">{running ? <><RefreshCw size={14} className="animate-spin" />RUNNING EVALUATION...</> : <><Play size={14} fill="currentColor" />{completed ? "RUN AGAIN" : "START FGSM EVALUATION"}</>}</button></div></div><div className="card-border rounded-xl bg-[#101725]/90 p-5"><div className="flex items-center gap-2"><Shield size={16} className="text-emerald-300" /><h2 className="text-sm font-bold text-white">Robustness snapshot</h2></div><p className="mt-1 text-sm text-slate-500">Latest completed evaluation</p><div className="mt-6 flex items-center justify-center"><div className="relative flex h-40 w-40 items-center justify-center rounded-full" style={{ background: "conic-gradient(#fca86a 0 73%, #243044 73% 100%)" }}><div className="flex h-32 w-32 flex-col items-center justify-center rounded-full bg-[#101725]"><span className="text-3xl font-bold text-white">73%</span><span className="text-[12px] text-slate-500">ROBUSTNESS</span></div></div></div><div className="mt-6 space-y-3">{[{ label: "Clean accuracy", value: "94.8%", color: "text-emerald-300" }, { label: "Adversarial accuracy", value: "76.2%", color: "text-amber-300" }, { label: "Confidence delta", value: "-18.6 pp", color: "text-rose-300" }].map(item => <div key={item.label} className="flex justify-between border-b border-slate-800/60 pb-3 text-sm last:border-0"><span className="text-slate-500">{item.label}</span><span className={cn("font-mono font-bold", item.color)}>{item.value}</span></div>)}</div></div></div></>;
}

function AnalyticsView() { return <><SectionHeader eyebrow="INTELLIGENCE / TELEMETRY" title="Security analytics" subtitle="Understand attack patterns, model behavior, and risk concentration across the estate." action={<button onClick={() => toast.success("Analytics export prepared", { description: "CSV is ready in Reports." })} className="flex items-center gap-2 rounded-lg border border-slate-700/60 bg-slate-900/30 px-3 py-2 text-sm font-bold text-slate-300 hover:border-cyan-300/40 hover:text-cyan-200"><Download size={13} />EXPORT DATA</button>} /><div className="grid gap-4 lg:grid-cols-3"><div className="card-border rounded-xl bg-[#101725]/90 p-5 lg:col-span-2"><h2 className="text-sm font-bold text-white">Risk score by hour</h2><p className="mt-1 text-sm text-slate-500">Average event risk across the detection plane</p><div className="mt-5 h-[230px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={[{ t: "00", risk: 18 }, { t: "04", risk: 21 }, { t: "08", risk: 36 }, { t: "12", risk: 52 }, { t: "16", risk: 44 }, { t: "20", risk: 31 }]}><CartesianGrid strokeDasharray="3 5" /><XAxis dataKey="t" tick={{ fill: "#65748a", fontSize: 10 }} axisLine={false} tickLine={false} /><YAxis tick={{ fill: "#65748a", fontSize: 10 }} axisLine={false} tickLine={false} /><Tooltip contentStyle={{ background: "#101a2a", border: "1px solid #2d415c", borderRadius: 8, fontSize: 11 }} /><Bar dataKey="risk" name="Average risk" fill="#aa91f8" radius={[4, 4, 0, 0]} /></BarChart></ResponsiveContainer></div></div><div className="card-border rounded-xl bg-[#101725]/90 p-5"><h2 className="text-sm font-bold text-white">Top impacted assets</h2><p className="mt-1 text-sm text-slate-500">By weighted event score</p><div className="mt-6 space-y-5">{[{ name: "api-gateway-02", score: 86, count: 214 }, { name: "auth-service", score: 71, count: 168 }, { name: "vpn-east-01", score: 53, count: 96 }, { name: "edge-proxy-01", score: 42, count: 73 }].map(item => <div key={item.name}><div className="mb-2 flex items-center justify-between"><span className="font-mono text-[12px] text-slate-300">{item.name}</span><span className="font-mono text-[12px] text-slate-500">{item.count} events</span></div><div className="h-1.5 rounded-full bg-slate-800"><div className={cn("h-full rounded-full", item.score > 80 ? "bg-rose-400" : item.score > 60 ? "bg-amber-300" : "bg-violet-300")} style={{ width: `${item.score}%` }} /></div></div>)}</div></div></div><div className="card-border mt-4 rounded-xl bg-[#101725]/90 p-5"><div className="flex items-center justify-between"><div><h2 className="text-sm font-bold text-white">Detection precision</h2><p className="mt-1 text-sm text-slate-500">False positives and true positives over the evaluation window</p></div><div className="flex gap-4 text-[12px] font-bold text-slate-500"><span className="flex items-center gap-2"><i className="h-1.5 w-5 rounded bg-cyan-300" />PRECISION</span><span className="flex items-center gap-2"><i className="h-1.5 w-5 rounded bg-violet-300" />RECALL</span></div></div><div className="mt-5 h-[200px]"><ResponsiveContainer width="100%" height="100%"><LineChart data={[{ d: "Mon", p: 91, r: 86 }, { d: "Tue", p: 93, r: 88 }, { d: "Wed", p: 92, r: 90 }, { d: "Thu", p: 95, r: 91 }, { d: "Fri", p: 94, r: 92 }, { d: "Sat", p: 96, r: 94 }, { d: "Sun", p: 96, r: 93 }]}><CartesianGrid strokeDasharray="3 5" /><XAxis dataKey="d" tick={{ fill: "#65748a", fontSize: 10 }} axisLine={false} tickLine={false} /><YAxis domain={[75, 100]} tick={{ fill: "#65748a", fontSize: 10 }} axisLine={false} tickLine={false} /><Tooltip contentStyle={{ background: "#101a2a", border: "1px solid #2d415c", borderRadius: 8, fontSize: 11 }} /><Line type="monotone" dataKey="p" name="Precision" stroke="#53d3f1" strokeWidth={2} dot={false} /><Line type="monotone" dataKey="r" name="Recall" stroke="#aa91f8" strokeWidth={2} dot={false} /></LineChart></ResponsiveContainer></div></div></>;
}

function DetectionsView() { const [filter, setFilter] = useState("ALL"); const rows = filter === "ALL" ? detectionRows : detectionRows.filter(r => r.status === filter); return <><SectionHeader eyebrow="OPERATIONS / TRIAGE" title="Detections" subtitle="Review, filter, and action the events surfaced by AdvSecure." action={<div className="flex gap-2"><button onClick={() => toast.success("All visible detections exported")} className="hidden items-center gap-2 rounded-lg border border-slate-700/60 px-3 py-2 text-sm font-bold text-slate-300 hover:text-white sm:flex"><Download size={13} />EXPORT</button><button onClick={() => toast.info("Triage queue assigned", { description: "12 events routed to the active SOC analyst." })} className="flex items-center gap-2 rounded-lg bg-rose-400 px-3 py-2 text-sm font-extrabold text-slate-950 hover:bg-rose-300"><ShieldAlert size={13} />TRIAGE QUEUE</button></div>} /><div className="card-border overflow-hidden rounded-xl bg-[#101725]/90"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-700/40 px-5 py-4"><div className="flex items-center gap-2"><Filter size={15} className="text-slate-500" /><span className="text-sm font-semibold text-slate-300">Filter by status</span><div className="ml-1 flex rounded-lg border border-slate-700/60 bg-slate-950/30 p-1">{["ALL", "BLOCKED", "REVIEW", "MONITOR"].map(item => <button key={item} onClick={() => setFilter(item)} className={cn("rounded px-2.5 py-1 text-[12px] font-bold", filter === item ? "bg-cyan-400/15 text-cyan-200" : "text-slate-500 hover:text-slate-300")}>{item}</button>)}</div></div><div className="flex items-center gap-2 font-mono text-[12px] text-slate-600"><ListFilter size={13} />{rows.length} VISIBLE EVENTS</div></div><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left"><thead><tr className="border-b border-slate-800/80 text-[12px] uppercase tracking-wider text-slate-600"><th className="px-5 py-3 font-medium">Timestamp / source</th><th className="px-4 py-3 font-medium">Classification</th><th className="px-4 py-3 font-medium">Model</th><th className="px-4 py-3 font-medium">Risk score</th><th className="px-4 py-3 font-medium">Action</th><th className="px-4 py-3"></th></tr></thead><tbody>{rows.map(row => <tr key={row.time} className="border-b border-slate-800/60 last:border-0 hover:bg-slate-800/20"><td className="px-5 py-4"><p className="font-mono text-[12px] text-slate-300">{row.time} UTC</p><p className="mt-1 font-mono text-[12px] text-slate-600">{row.source} → {row.target}</p></td><td className="px-4 py-4"><span className="text-sm font-semibold text-slate-300">{row.type}</span></td><td className="px-4 py-4"><Pill tone={row.model === "DNN" ? "violet" : "cyan"}>{row.model}</Pill></td><td className="px-4 py-4"><span className={cn("font-mono text-sm font-bold", row.score > 90 ? "text-rose-300" : "text-amber-300")}>{row.score}</span><span className="ml-2 text-[12px] text-slate-600">/ 100</span></td><td className="px-4 py-4"><Pill tone={row.color === "red" ? "red" : row.color === "amber" ? "amber" : "violet"}>{row.status}</Pill></td><td className="px-4 py-4"><button onClick={() => toast.info("Detection details opened", { description: `${row.type} from ${row.source}` })} className="rounded p-1.5 text-slate-600 hover:bg-slate-800 hover:text-slate-200"><MoreHorizontal size={16} /></button></td></tr>)}</tbody></table></div></div></>; }

function LogsView() { const [query, setQuery] = useState(""); const rows = logRows.filter(row => `${row.event} ${row.actor} ${row.detail}`.toLowerCase().includes(query.toLowerCase())); return <><SectionHeader eyebrow="GOVERNANCE / TRACEABILITY" title="Audit logs" subtitle="Immutable activity record for analysts, models, and automated policy actions." action={<button onClick={() => toast.success("Audit log export prepared")} className="flex items-center gap-2 rounded-lg border border-slate-700/60 bg-slate-900/30 px-3 py-2 text-sm font-bold text-slate-300 hover:border-cyan-300/40 hover:text-cyan-200"><Download size={13} />EXPORT LOG</button>} /><div className="card-border overflow-hidden rounded-xl bg-[#101725]/90"><div className="flex items-center gap-3 border-b border-slate-700/40 p-4"><div className="relative flex-1"><Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-600" /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search event, actor, or detail..." className="w-full rounded-lg border border-slate-700/70 bg-slate-950/30 py-2.5 pl-9 pr-3 text-sm text-slate-200 outline-none placeholder:text-slate-600 focus:border-cyan-300/40" /></div><button onClick={() => setQuery("")} className="rounded-lg border border-slate-700/60 p-2.5 text-slate-500 hover:text-white"><RefreshCw size={14} /></button></div><div className="divide-y divide-slate-800/60">{rows.map(row => <div key={row.time + row.event} className="flex items-center gap-4 px-5 py-4 hover:bg-slate-800/20"><div className={cn("hidden h-8 w-8 items-center justify-center rounded-lg sm:flex", row.kind === "ACTION" ? "bg-rose-400/10 text-rose-300" : row.kind === "LAB" ? "bg-amber-400/10 text-amber-300" : row.kind === "AUTH" ? "bg-violet-400/10 text-violet-300" : "bg-cyan-400/10 text-cyan-300")}><Terminal size={14} /></div><div className="min-w-0 flex-1"><p className="text-sm font-semibold text-slate-300">{row.event}</p><p className="mt-1 truncate font-mono text-[12px] text-slate-600">{row.actor} · {row.detail}</p></div><div className="hidden text-right sm:block"><Pill tone="slate">{row.kind}</Pill></div><span className="font-mono text-[12px] text-slate-600">{row.time}</span></div>)}</div></div></>; }

function ReportsView() { const reportMutation = trpc.advsecure.requestReport.useMutation(); const reports = [{ title: "Daily SOC posture", date: "11 Sep 2026 · 11:45 UTC", type: "Operational summary", icon: FileBarChart2, tone: "cyan" }, { title: "Adversarial robustness review", date: "10 Sep 2026 · 16:20 UTC", type: "Model evaluation", icon: Bug, tone: "amber" }, { title: "CICIDS2017 validation run", date: "09 Sep 2026 · 09:10 UTC", type: "Dataset analysis", icon: Database, tone: "violet" }]; return <><SectionHeader eyebrow="GOVERNANCE / OUTPUTS" title="Reports" subtitle="Exportable artifacts for review boards, incident response, and model governance." action={<button onClick={() => toast.info("Report generator opened", { description: "Choose a report template to continue." })} className="flex items-center gap-2 rounded-lg bg-cyan-300 px-3 py-2 text-sm font-extrabold text-slate-950 hover:bg-cyan-200"><Sparkles size={13} />NEW REPORT</button>} /><div className="grid gap-4 md:grid-cols-3">{reports.map(report => <div key={report.title} className="card-border rounded-xl bg-[#101725]/90 p-5 transition hover:-translate-y-0.5 hover:border-slate-600/70"><div className="flex items-start justify-between"><div className={cn("rounded-lg p-2.5", report.tone === "cyan" ? "bg-cyan-400/10 text-cyan-300" : report.tone === "amber" ? "bg-amber-400/10 text-amber-300" : "bg-violet-400/10 text-violet-300")}><report.icon size={17} /></div><button onClick={() => toast.info("Report actions opened")} className="text-slate-600 hover:text-white"><MoreHorizontal size={16} /></button></div><h2 className="mt-5 text-sm font-bold text-white">{report.title}</h2><p className="mt-2 text-sm text-slate-500">{report.type}</p><p className="mt-4 font-mono text-[12px] text-slate-600">{report.date}</p><button onClick={() => reportMutation.mutate({ title: report.title, type: report.type as "Operational summary" | "Model evaluation" | "Dataset analysis" }, { onSuccess: () => toast.success("Report request persisted", { description: `${report.title} is queued for PDF assembly.` }), onError: error => toast.error("Report request failed", { description: error.message }) })} className="mt-5 flex w-full items-center justify-center gap-2 rounded-lg border border-slate-700/60 py-2 text-[12px] font-bold tracking-wider text-slate-300 hover:border-cyan-300/40 hover:text-cyan-200"><Download size={13} />EXPORT PDF</button></div>)}</div><div className="card-border mt-4 rounded-xl bg-[#101725]/90 p-5"><div className="flex items-center gap-2"><Archive size={16} className="text-slate-400" /><h2 className="text-sm font-bold text-white">Report pipeline</h2></div><p className="mt-1 text-sm text-slate-500">Incident PDF generation is staged for final review.</p><div className="mt-6 grid gap-3 md:grid-cols-4">{["Template selected", "Telemetry snapshot", "Threat narrative", "PDF assembly"].map((step, i) => <div key={step} className="flex items-center gap-3 rounded-lg border border-slate-800/70 bg-slate-950/20 p-3"><span className={cn("flex h-6 w-6 items-center justify-center rounded-full text-[12px] font-bold", i < 3 ? "bg-emerald-400/15 text-emerald-300" : "bg-slate-800 text-slate-500")}>{i < 3 ? "✓" : i + 1}</span><span className="text-[12px] font-semibold text-slate-400">{step}</span></div>)}</div></div></>; }

function SettingsView() { const [toggles, setToggles] = useState({ autoBlock: true, sync: true, alerts: false }); const flip = (key: keyof typeof toggles) => setToggles(value => ({ ...value, [key]: !value[key] })); return <><SectionHeader eyebrow="GOVERNANCE / CONTROL PLANE" title="Settings" subtitle="Configure how AdvSecure ingests, detects, and escalates security events." action={<button onClick={() => toast.success("Settings saved", { description: "Control plane configuration updated." })} className="flex items-center gap-2 rounded-lg bg-cyan-300 px-3 py-2 text-sm font-extrabold text-slate-950 hover:bg-cyan-200"><KeyRound size={13} />SAVE CHANGES</button>} /><div className="grid gap-4 lg:grid-cols-[1fr_1fr]"><div className="card-border rounded-xl bg-[#101725]/90 p-5"><div className="flex items-center gap-2"><Shield size={16} className="text-cyan-300" /><h2 className="text-sm font-bold text-white">Detection policy</h2></div><p className="mt-1 text-sm text-slate-500">Guardrails for automated response behavior</p><div className="mt-6 space-y-2">{[{ key: "autoBlock", title: "Auto-block high risk events", detail: "Enforce policy when risk score exceeds 90", icon: ShieldAlert }, { key: "sync", title: "Threat intelligence sync", detail: "Refresh IOC feeds every 15 minutes", icon: Globe2 }, { key: "alerts", title: "Analyst email alerts", detail: "Notify on new critical detections", icon: Bell }].map(item => <div key={item.key} className="flex items-center gap-3 rounded-lg border border-slate-800/70 bg-slate-950/20 p-4"><div className="rounded-lg bg-slate-800/60 p-2 text-slate-400"><item.icon size={15} /></div><div className="min-w-0 flex-1"><p className="text-sm font-semibold text-slate-300">{item.title}</p><p className="mt-1 text-[12px] text-slate-600">{item.detail}</p></div><button onClick={() => flip(item.key as keyof typeof toggles)} className={cn("relative h-5 w-9 rounded-full transition", toggles[item.key as keyof typeof toggles] ? "bg-cyan-300" : "bg-slate-700")}><span className={cn("absolute top-1 h-3 w-3 rounded-full transition", toggles[item.key as keyof typeof toggles] ? "left-5 bg-slate-950" : "left-1 bg-slate-400")} /></button></div>)}</div></div><div className="card-border rounded-xl bg-[#101725]/90 p-5"><div className="flex items-center gap-2"><LockKeyhole size={16} className="text-violet-300" /><h2 className="text-sm font-bold text-white">System configuration</h2></div><p className="mt-1 text-sm text-slate-500">Environment and model pipeline metadata</p><div className="mt-6 space-y-4">{[{ label: "Environment", value: "PRODUCTION-SIMULATION", icon: Server }, { label: "Dataset", value: "CICIDS2017 · VALIDATED", icon: Database }, { label: "Preprocessing", value: "scaler.pkl · 78 features", icon: SlidersHorizontal }, { label: "API status", value: "FastAPI / v1 · healthy", icon: Terminal }].map(item => <div key={item.label} className="flex items-center gap-3 border-b border-slate-800/60 pb-4 last:border-0"><item.icon size={15} className="text-slate-500" /><span className="flex-1 text-sm text-slate-500">{item.label}</span><span className="font-mono text-[12px] font-bold text-slate-300">{item.value}</span></div>)}</div><div className="mt-2 rounded-lg border border-amber-400/20 bg-amber-400/5 p-3"><div className="flex gap-2"><AlertCircle size={14} className="mt-0.5 shrink-0 text-amber-300" /><p className="text-[12px] leading-5 text-amber-200/70">Authentication, Docker, MLflow, Prometheus, and Grafana are planned for the final implementation review.</p></div></div></div></div></>; }

function AppView({ view, onNavigate }: { view: string; onNavigate: (id: string) => void }) { switch (view) { case "monitor": return <MonitorView />; case "models": return <ModelsView />; case "adversarial": return <AdversarialView />; case "analytics": return <AnalyticsView />; case "detections": return <DetectionsView />; case "logs": return <LogsView />; case "reports": return <ReportsView />; case "settings": return <SettingsView />; default: return <DashboardView onNavigate={onNavigate} />; } }

export default function Home() {
  const [active, setActive] = useState("overview"); const [mobileOpen, setMobileOpen] = useState(false); const [searchOpen, setSearchOpen] = useState(false);
  const activeLabel = useMemo(() => navGroups.flatMap(group => group.items).find(item => item.id === active)?.label ?? "Command center", [active]);
  const navigate = (id: string) => { setActive(id); setMobileOpen(false); window.scrollTo({ top: 0, behavior: "smooth" }); };
  return <div className="min-h-screen bg-[#080c14] text-slate-200"><aside className={cn("fixed inset-y-0 left-0 z-40 flex w-[248px] flex-col border-r border-slate-800/70 bg-[#0a0f18] transition-transform duration-200 lg:translate-x-0", mobileOpen ? "translate-x-0" : "-translate-x-full")}><div className="flex h-[72px] items-center justify-between border-b border-slate-800/70 px-5"><button onClick={() => navigate("overview")} className="flex items-center gap-3 text-left"><div className="relative flex h-9 w-9 items-center justify-center rounded-xl bg-cyan-300 text-slate-950 shadow-[0_0_22px_rgba(83,211,241,.24)]"><Hexagon size={20} fill="currentColor" /><Shield size={11} className="absolute" /></div><div><p className="text-[15px] font-extrabold tracking-tight text-white">Adv<span className="text-cyan-300">Secure</span></p><p className="font-mono text-[12px] uppercase tracking-[.16em] text-slate-600">AI SECURITY OPS</p></div></button><button onClick={() => setMobileOpen(false)} className="rounded p-1 text-slate-500 lg:hidden"><X size={17} /></button></div><div className="mx-4 mt-5 flex items-center gap-3 rounded-xl border border-cyan-300/15 bg-cyan-300/5 px-3 py-3"><div className="relative"><span className="status-dot pulse-cyan bg-emerald-300" /><span className="absolute -inset-1 rounded-full border border-emerald-300/20" /></div><div className="min-w-0"><p className="text-[12px] font-bold text-emerald-200">SYSTEM OPERATIONAL</p><p className="mt-0.5 truncate text-[12px] text-slate-500">All detection services healthy</p></div></div><nav className="mt-6 flex-1 overflow-y-auto px-3">{navGroups.map(group => <div key={group.label} className="mb-6"><p className="mb-2 px-3 font-mono text-[12px] font-medium tracking-[.2em] text-slate-600">{group.label}</p><div className="space-y-0.5">{group.items.map(item => <button key={item.id} onClick={() => navigate(item.id)} className={cn("group flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left transition", active === item.id ? "bg-cyan-300/10 text-cyan-200" : "text-slate-500 hover:bg-slate-800/40 hover:text-slate-200")}><item.icon size={15} className={cn(active === item.id ? "text-cyan-300" : "text-slate-600 group-hover:text-slate-300")} /><span className="flex-1 text-sm font-semibold">{item.label}</span>{item.badge && <span className={cn("rounded px-1.5 py-0.5 font-mono text-[12px] font-bold", item.badge === "LIVE" ? "bg-emerald-400/10 text-emerald-300" : item.badge === "LAB" ? "bg-amber-400/10 text-amber-300" : "bg-slate-800 text-slate-500")}>{item.badge}</span>}</button>)}</div></div>)}</nav><div className="border-t border-slate-800/70 p-3"><button onClick={() => toast.info("Profile menu opened", { description: "SOC Analyst · a.khan@advsecure.local" })} className="flex w-full items-center gap-3 rounded-lg p-2 text-left transition hover:bg-slate-800/40"><div className="flex h-8 w-8 items-center justify-center rounded-full bg-gradient-to-br from-violet-300 to-cyan-300 text-sm font-extrabold text-slate-950">AK</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold text-slate-300">Aarav Khan</p><p className="truncate font-mono text-[12px] text-slate-600">SOC ANALYST · L2</p></div><ChevronDown size={14} className="text-slate-600" /></button></div></aside>{mobileOpen && <button onClick={() => setMobileOpen(false)} className="fixed inset-0 z-30 bg-slate-950/70 lg:hidden" aria-label="Close navigation" />}<main className="min-h-screen lg:pl-[248px]"><header className="sticky top-0 z-20 flex h-[72px] items-center justify-between border-b border-slate-800/70 bg-[#080c14]/85 px-4 backdrop-blur-xl sm:px-6 lg:px-8"><div className="flex items-center gap-3"><button onClick={() => setMobileOpen(true)} className="rounded-lg border border-slate-700/60 p-2 text-slate-400 lg:hidden"><Menu size={17} /></button><div className="hidden items-center gap-2 text-[12px] font-bold text-slate-600 sm:flex"><span className="text-slate-500">ADVSECURE</span><ChevronRight size={12} /><span className="text-slate-300">{activeLabel.toUpperCase()}</span></div><div className="flex items-center gap-2 sm:hidden"><span className="status-dot bg-cyan-300" /><span className="font-mono text-[12px] font-bold tracking-wider text-slate-400">SOC / {activeLabel.toUpperCase()}</span></div></div><div className="flex items-center gap-2"><div className={cn("hidden items-center rounded-lg border border-slate-700/60 bg-slate-900/30 transition sm:flex", searchOpen ? "w-64" : "w-9")}><button onClick={() => setSearchOpen(!searchOpen)} className="p-2 text-slate-500 hover:text-cyan-300"><Search size={15} /></button>{searchOpen && <input autoFocus onKeyDown={e => e.key === "Escape" && setSearchOpen(false)} placeholder="Search events..." className="w-full bg-transparent pr-3 text-sm text-slate-200 outline-none placeholder:text-slate-600" />}</div><button onClick={() => toast.info("No new critical notifications", { description: "Your alert queue is clear." })} className="relative rounded-lg border border-slate-700/60 bg-slate-900/30 p-2 text-slate-500 hover:text-cyan-300"><Bell size={15} /><span className="absolute right-1.5 top-1.5 h-1.5 w-1.5 rounded-full bg-rose-400" /></button><button onClick={() => navigate("settings")} className="rounded-lg border border-slate-700/60 bg-slate-900/30 p-2 text-slate-500 hover:text-white"><Settings2 size={15} /></button></div></header><div className="console-grid min-h-[calc(100vh-72px)] px-4 py-6 sm:px-6 lg:px-8"><div className="mx-auto max-w-[1480px]"><div className="mb-5 flex items-center justify-between"><div className="flex items-center gap-2 text-[12px] text-slate-600"><span className="font-mono">SEP 11, 2026</span><span>·</span><span className="font-mono">11:52:21 UTC</span><span className="hidden text-slate-700 sm:inline">·</span><span className="hidden items-center gap-1.5 sm:flex"><span className="status-dot bg-emerald-300" />REAL-TIME TELEMETRY</span></div><div className="hidden items-center gap-2 text-[12px] font-bold tracking-wider text-slate-600 md:flex"><LockKeyhole size={12} />SECURE CONSOLE <span className="text-slate-800">/</span> <span className="text-cyan-300/70">TENANT: ADV-OPS-01</span></div></div><AppView view={active} onNavigate={navigate} /></div></div></main></div>;
}
